import numpy as np, time
import scipy.linalg as sla
# compare overheads
for n in [2,4,6,8,10]:
    A=np.random.normal(size=(n,n))
    # warm
    for _ in range(50): np.linalg.eig(A)
    t0=time.perf_counter()
    for _ in range(2000): np.linalg.eig(A)
    t1=time.perf_counter()
    print(f"np.linalg.eig {n}: {(t1-t0)/2000*1e6:.2f} us")
    for _ in range(50): sla.eig(A, overwrite_a=False, check_finite=False)
    t0=time.perf_counter()
    for _ in range(2000): sla.eig(A, overwrite_a=False, check_finite=False)
    t1=time.perf_counter()
    print(f"scipy eig nofinite {n}: {(t1-t0)/2000*1e6:.2f} us")
    try:
        from scipy.linalg.lapack import dgeev
        # warm: dgeev needs overwrite_a? signature: (a, compute_vl, compute_vr, ...)
        for _ in range(50): dgeev(A, compute_vl=0, compute_vr=1, overwrite_a=0)
        t0=time.perf_counter()
        for _ in range(2000): dgeev(A, compute_vl=0, compute_vr=1, overwrite_a=0)
        t1=time.perf_counter()
        print(f"dgeev direct {n}: {(t1-t0)/2000*1e6:.2f} us")
    except Exception as e:
        print("dgeev fail", e)
